  // campo se llene entero): sólo contagian las ondas jóvenes.
  if (v0.g < mejor.g && v0.g < uLimite) mejor = v0;
  if (v1.g < mejor.g && v1.g < uLimite) mejor = v1;
  if (v2.g < mejor.g && v2.g < uLimite) mejor = v2;
  if (v3.g < mejor.g && v3.g < uLimite) mejor = v3;
  mejor.g += uAvance;

